dplyr grammar
What’s the advantage of dplyr grammar? We can sequence data manipulation!



gss_all |&gt; 
  filter(year == 2022) |&gt;
  drop_na(sex, agekdbrn) |&gt;
  group_by(sex) |&gt;
  summarize(avg = mean(agekdbrn))


# A tibble: 2 × 2
  sex          avg
  &lt;dbl+lbl&gt;  &lt;dbl&gt;
1 1 [male]    26.3
2 2 [female]  23.7

Assignment: Overwriting (cont)



Do something, save result, not overwriting original.


gss_all &lt;-  gss_all |&gt;  
  mutate(age_groups = case_when(
    agekdbrn &lt; 18 ~ "&lt;18",
    agekdbrn &gt;= 18 & agekdbrn &lt;= 29 ~ "18–29",
    agekdbrn &gt;= 30 & agekdbrn &lt;= 39 ~ "30–39",
    agekdbrn &gt;= 40 ~ "40+",
    TRUE ~ NA_character_)
  ) 

gss_all |&gt;
  filter(year == 2022) |&gt;
  freq(age_groups, report.nas = FALSE, headings = FALSE)



Do something and show me


gss_all |&gt;  
  select(year, agekdbrn) |&gt; 
  filter(year == 2022) |&gt; 
  drop_na(agekdbrn)  |&gt;
  mutate(age_groups = case_when(
    agekdbrn &lt; 18 ~ "&lt;18",
    agekdbrn &gt;= 18 & agekdbrn &lt;= 29 ~ "18–29",
    agekdbrn &gt;= 30 & agekdbrn &lt;= 39 ~ "30–39",
    agekdbrn &gt;= 40 ~ "40+",
    TRUE ~ NA_character_)) |&gt;
  group_by(age_groups) |&gt;  
  summarise(
    count = n(),
    proportion = round(count / sum(count), 3)
  )

summarize()
Use functions inside summarize() to create summary variables.



gss_all |&gt;  
  drop_na(agekdbrn) |&gt;
   summarize(
    avg = mean(agekdbrn)
    ) 


# A tibble: 1 × 1
    avg
  &lt;dbl&gt;
1  24.1

